"""Shipped gated-activation configurations shared by AOT and dispatch."""

SILU_INTERLEAVED_HIDDEN = (
    512,
    1024,
    3584,
    6144,
    8960,
    9216,
    12288,
    17408,
)

GELU_TANH_CONTIGUOUS_HIDDEN = (
    704,
    2112,
    3072,
    4304,
    6144,
    10240,
    12288,
    20480,
    21504,
    43008,
)

GELU_TANH_INTERLEAVED_HIDDEN = (
    2112,
    6144,
    10240,
    12288,
    21504,
)

GATED_ACTIVATION_CONFIGS = tuple(
    ("silu", "interleaved_i8", hidden)
    for hidden in SILU_INTERLEAVED_HIDDEN
) + tuple(
    ("gelu_tanh", "contiguous", hidden)
    for hidden in GELU_TANH_CONTIGUOUS_HIDDEN
) + tuple(
    ("gelu_tanh", "interleaved_i8", hidden)
    for hidden in GELU_TANH_INTERLEAVED_HIDDEN
)


def gated_activation_variant_key(
    activation: str,
    layout: str,
    hidden: int,
) -> str:
    if activation == "silu" and layout == "interleaved_i8":
        return f"bf16_h{hidden}_i8"
    return f"bf16_h{hidden}_{activation}_{layout}"


GATED_ACTIVATION_CONFIG_BY_KEY = {
    gated_activation_variant_key(activation, layout, hidden): (
        activation,
        layout,
        hidden,
    )
    for activation, layout, hidden in GATED_ACTIVATION_CONFIGS
}

__all__ = [
    "GATED_ACTIVATION_CONFIGS",
    "GATED_ACTIVATION_CONFIG_BY_KEY",
    "gated_activation_variant_key",
]
